def vincular_chamados_aos_ativos(apps, schema_editor):
    """Liga os chamados já existentes ao ativo cujo código abre o texto."""
    Ativo = apps.get_model('chamados', 'Ativo')
    Chamado = apps.get_model('chamados', 'Chamado')
    por_codigo = {a.codigo.lower(): a.pk for a in Ativo.objects.all()}
    for chamado in Chamado.objects.filter(ativo_ref__isnull=True).exclude(ativo=''):
        texto = chamado.ativo.strip().lower()
        pk = por_codigo.get(texto) or (por_codigo.get(texto.split()[0]) if texto else None)
        if pk:
            Chamado.objects.filter(pk=chamado.pk).update(ativo_ref_id=pk)


